# Generated by build.py from recipe.yml for recipe smtp-serve-a-mail-domain. Do not edit.
set -e
cd "$(dirname "$0")"
awk '{printf "%s\r\n", $0}' > mail.txt <<'EOF'
From: ann@example.com
To: bob@example.com
Subject: Lunch

Noon at the usual place.
EOF
surl --mail-domain example.com --mailbox ann@example.com:secret --mailbox bob@example.com:hunter2 smtp://127.0.0.1:8080/ imap://127.0.0.1:8081/ &
sleep 1
curl -s -u ann@example.com:secret --mail-from ann@example.com --mail-rcpt bob@example.com -T mail.txt smtp://127.0.0.1:8080/
kill $(jobs -p)
